-- Full visual redesign of every notification email template's HTML content:
-- shared premium chrome (logo lockup, accent bar, hidden preheader text, dark-mode-safe
-- meta tags), restyled CTAs/callouts/tables per template. Same {{placeholders}} throughout,
-- so no Java-side variable wiring changes are required. Subjects are unchanged.

UPDATE notification_templates SET
    message_body = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>PortfoliosBuilder</title><style>@media only screen and (max-width:600px){.email-container{width:100% !important}.email-body{padding:30px 22px !important}.email-header{padding:30px 24px 26px !important}}</style></head><body style="margin:0;padding:0;background:#eef1f6;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif"><div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Your PortfoliosBuilder verification code is inside — it expires soon.&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:40px 16px"><tr><td align="center"><table role="presentation" class="email-container" width="560" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 2px 6px rgba(15,23,42,.06),0 16px 40px -12px rgba(15,23,42,.18);max-width:560px"><tr><td class="email-header" style="background:linear-gradient(135deg,#059669,#047857);padding:34px 36px 30px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="vertical-align:middle"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:26px;height:26px;border-radius:8px;background:rgba(255,255,255,0.22);text-align:center;vertical-align:middle;font-size:13px;font-weight:800;color:#ffffff;line-height:26px">P</td><td style="padding-left:8px;color:#d1fae5;font-size:12.5px;font-weight:700;letter-spacing:0.02em">PortfoliosBuilder</td></tr></table></td><td align="right" style="vertical-align:middle"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:42px;height:42px;border-radius:12px;background:rgba(255,255,255,0.16);text-align:center;vertical-align:middle;font-size:20px;line-height:42px">&#128272;</td></tr></table></td></tr></table><h1 style="color:#ffffff;font-size:22px;margin:20px 0 0;font-weight:800;letter-spacing:-0.01em;line-height:1.3">Verify Your Email</h1><p style="color:#a7f3d0;font-size:13.5px;margin:6px 0 0;font-weight:500">One quick step to confirm it is really you</p></td></tr><tr><td style="height:3px;background:linear-gradient(90deg,#34d399,#059669,#047857);font-size:0;line-height:0">&nbsp;</td></tr><tr><td class="email-body" style="padding:36px 36px 8px"><p style="color:#374151;font-size:15px;margin:0 0 18px;line-height:1.6">Hi <strong>{{fullName}}</strong>,</p><p style="color:#374151;font-size:15px;margin:0 0 24px;line-height:1.6">Use the code below to verify your email address. It expires in <strong>{{expiryMinutes}} minutes</strong>.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 26px"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" style="background:#ecfdf5;border:1.5px dashed #059669;border-radius:14px"><tr><td style="padding:20px 44px;text-align:center"><p style="font-size:11px;font-weight:700;color:#047857;letter-spacing:0.12em;text-transform:uppercase;margin:0 0 8px">Verification Code</p><span style="font-size:36px;font-weight:800;letter-spacing:11px;color:#047857">{{otp}}</span></td></tr></table></td></tr></table><p style="color:#9ca3af;font-size:13px;margin:0;line-height:1.6">Did not request this code? You can safely ignore this email — no changes will be made to your account.</p></td></tr><tr><td style="padding:24px 36px 30px;border-top:1px solid #f1f5f9;background:#fafbfc"><p style="color:#9ca3af;font-size:12px;margin:0;line-height:1.7">This is an automated message from PortfoliosBuilder.</p><p style="color:#cbd5e1;font-size:10.5px;margin:10px 0 0;font-weight:700;letter-spacing:0.04em">PORTFOLIOSBUILDER — BUILD. SHOWCASE. GROW.</p></td></tr></table></td></tr></table></body></html>'
WHERE template = 'OTP-VERIFICATION';

